<script setup lang="ts">
import { computed, onMounted, ref, watch } from "vue"; import { http } from "@/utils/http";
type Row = Record<string, any>; const tab = ref("sources"); const query = ref(""); const sources = ref<Row[]>([]); const runs = ref<Row[]>([]); const items = ref<Row[]>([]); const loading = ref(false); const error = ref(""); const selectedRun = ref<Row | null>(null); const filteredSources = computed(() => sources.value.filter(row => !query.value || JSON.stringify(row).toLowerCase().includes(query.value.toLowerCase()))); const filteredRuns = computed(() => runs.value.filter(row => !query.value || JSON.stringify(row).toLowerCase().includes(query.value.toLowerCase())));
async function load() { loading.value = true; error.value = ""; try { if (tab.value === "sources") { const result = await http.get<unknown, unknown>("/ingestion/sources"); sources.value = Array.isArray(result) ? result as Row[] : []; } else { const result = await http.get<unknown, unknown>("/ingestion/runs"); runs.value = Array.isArray(result) ? result as Row[] : []; } } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "内容导入数据加载失败"; } finally { loading.value = false; } }
async function openRun(run: Row) { selectedRun.value = run; try { const result = await http.get<unknown, unknown>(`/ingestion/runs/${run.id}/items`); items.value = Array.isArray(result) ? result as Row[] : []; } catch (e: any) { error.value = e?.response?.data?.detail || "导入项目加载失败"; } } async function cancelRun(run: Row) { if (!run.id || !window.confirm("确认取消该导入运行？已完成项目将保留。")) return; try { await http.delete(`/ingestion/runs/${run.id}`); await load(); } catch (e: any) { error.value = e?.response?.data?.detail || "取消导入失败"; } } async function retry(item: Row) { if (!selectedRun.value?.id || !item.id) return; try { await http.post(`/ingestion/runs/${selectedRun.value.id}/items/${item.id}/retry`); await openRun(selectedRun.value); } catch (e: any) { error.value = e?.response?.data?.detail || "重试失败"; } }
watch(tab, load); onMounted(load);
</script>
<template><main class="p-4 md:p-6"><div class="flex justify-between items-start mb-6"><div><h1 class="text-2xl font-semibold">内容导入</h1><p class="mt-1 text-[var(--el-text-color-secondary)]">管理导入来源、扫描任务和失败项目；导入过程由后台任务执行。</p></div><el-button :loading="loading" @click="load">刷新</el-button></div><el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="mb-4"/><el-tabs v-model="tab"><el-tab-pane label="来源" name="sources"/><el-tab-pane label="扫描 / 导入任务" name="scans"/><el-tab-pane label="失败项目" name="failed"/></el-tabs><el-card shadow="never"><template #header><div class="flex justify-between items-center"><span>{{ tab === 'sources' ? '导入来源' : tab === 'scans' ? '扫描与导入运行' : '失败项目' }}</span><el-input v-model="query" clearable placeholder="搜索名称或任务 ID" class="w-64"/></div></template><el-skeleton v-if="loading" :rows="7" animated/><template v-else-if="tab === 'sources'"><el-empty v-if="!filteredSources.length" description="暂无导入来源"/><el-table v-else :data="filteredSources" stripe><el-table-column prop="name" label="来源名称" min-width="220"/><el-table-column prop="type" label="类型" width="140"/><el-table-column prop="location" label="位置摘要" min-width="240"/><el-table-column prop="enabled" label="启用" width="100"/><el-table-column prop="updatedAt" label="更新时间" min-width="180"/></el-table></template><template v-else-if="tab === 'scans'"><el-empty v-if="!filteredRuns.length" description="暂无导入运行"/><el-table v-else :data="filteredRuns" stripe><el-table-column prop="id" label="Run ID" min-width="230"/><el-table-column prop="sourceId" label="来源" min-width="180"/><el-table-column prop="status" label="状态" width="130"/><el-table-column prop="completedCount" label="已完成" width="100"/><el-table-column prop="failedCount" label="失败" width="90"/><el-table-column prop="startedAt" label="开始时间" min-width="180"/><el-table-column label="操作" width="150"><template #default="{ row }"><el-button link @click="openRun(row)">查看项目</el-button><el-button link type="danger" @click="cancelRun(row)">取消</el-button></template></el-table-column></el-table></template><template v-else><el-table :data="items.filter(item => String(item.status).toUpperCase() === 'FAILED')" stripe><el-table-column prop="id" label="Item ID" min-width="220"/><el-table-column prop="sourceLabel" label="来源" min-width="180"/><el-table-column prop="errorCategory" label="失败分类" width="150"/><el-table-column prop="errorMessage" label="安全错误摘要" min-width="260"/><el-table-column label="操作" width="90"><template #default="{ row }"><el-button link @click="retry(row)">重试</el-button></template></el-table-column></el-table><el-empty v-if="!items.filter(item => String(item.status).toUpperCase() === 'FAILED').length" description="暂无失败项目；请先从扫描任务打开运行详情"/></template></el-card></main></template>
